import useProcessMessage from '@/services/JsBridge/useProcessMessage';
import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { useGlobalStore } from '@/store';
import { Outlet, history } from '@umijs/max';
import { Layout, Spin } from 'antd';
import { disable, enable, setFetchMethod } from 'darkreader';
import 'highlight.js/styles/atom-one-dark.css';
import { FC, useCallback, useEffect } from 'react';
import styles from './index.module.less';
import useChangeRoute from './useChangeRoute';

const BasicLayout: FC = () => {
  useProcessMessage();
  const { setPluginConfig, setProjectConfig, pluginConfig, projectConfig } =
    useGlobalStore();
  const { theme: pluginTheme = 'dark' } = pluginConfig;
  useChangeRoute();

  // 插件配置同步
  useEffect(() => {
    console.log('【插件注入配置信息 pluginConfig】：', window.pluginConfig);
    setPluginConfig({ ...pluginConfig, ...window.pluginConfig });
    if (window?.projectConfig) {
      console.log('【插件注入配置信息 projectConfig】：', window.projectConfig);
      setProjectConfig({ ...projectConfig, ...window.projectConfig });
    }
  }, []);

  const onPluginConfigChange = useCallback(
    (newPluginConfig: Partial<Window['pluginConfig']>) => {
      console.log('同步用户信息配置pluginConfig：', newPluginConfig);
      setPluginConfig({ ...pluginConfig, ...newPluginConfig });
      window.pluginConfig = {
        ...window.pluginConfig,
        ...newPluginConfig,
      };
    },
    [setPluginConfig, pluginConfig, projectConfig],
  );

  useRegisterMessage('syncPluginConfig', onPluginConfigChange);

  // 项目配置同步
  const onProjectConfigChange = useCallback(
    (newProjectConfig: Partial<Window['projectConfig']>) => {
      console.log('同步项目配置ProjectConfig：', newProjectConfig);
      const resProjectConfig = {
        ...(window.projectConfig ?? {}),
        ...projectConfig,
        ...newProjectConfig,
      };
      setProjectConfig(resProjectConfig);
      window.projectConfig = resProjectConfig;
    },
    [setProjectConfig, projectConfig],
  );
  useRegisterMessage('syncProjectConfig', onProjectConfigChange);

  useEffect(() => {
    setFetchMethod((url) => {
      const headers = new Headers();
      headers.append('Access-Control-Allow-Origin', '*');
      return window.fetch(url, {
        headers,
        mode: 'no-cors',
      });
    });
  }, []);

  useEffect(() => {
    if (pluginTheme === 'dark') {
      enable(
        {
          brightness: 100,
          contrast: 100,
          sepia: 0,
        },
        {
          css: `
          .cm-content .cm-line {caret-color:white !important }
          .mermaid * {
              fill: inherit !important;
            }`,
          ignoreImageAnalysis: [],
          ignoreInlineStyle: [],
          invert: ['.darkreaderIgnore'],
          disableStyleSheetsProxy: true,
        },
      );
    } else {
      disable();
    }
  }, [pluginTheme]);

  const { redirectPath } = window;
  useEffect(() => {
    if (redirectPath) {
      setTimeout(() => {
        history.push(redirectPath);
      }, 0);
      window.redirectPath = undefined;
    }
  }, [redirectPath]);

  return redirectPath ? (
    <Spin />
  ) : (
    <Layout className={styles.layout}>
      <Layout.Content className={styles.content}>
        <Outlet />
      </Layout.Content>
    </Layout>
  );
};
export default BasicLayout;
