import { StateCreator } from 'zustand';
import { StoreActions, StoreState } from './types';

export const actions: StateCreator<
  StoreState & StoreActions,
  [],
  [],
  StoreActions
> = (set, get) => ({
  setPluginConfig: (data) => {
    set(() => ({
      pluginConfig: data,
    }));
  },
  setDisplayModel: (displayModel) => {
    set(() => ({
      displayModel,
    }));
  },
  setProjectConfig: (data) => {
    set(() => ({
      projectConfig: data,
    }));
  },
});
