import { useModel } from '@umijs/max';
import { useEffect, useRef } from 'react';

export default function useRegisterMessage<
  T extends JsBridgeMessage.PluginToWebviewMessage = JsBridgeMessage.PluginToWebviewMessage,
>(
  command: T['command'],
  handler: (data: T['data']) => void,
  otherDeps: any[] = [],
) {
  const { register, unregister } = useModel('messageRegister');
  const idRef = useRef<symbol>();
  useEffect(() => {
    idRef.current = register(command, handler);
    return () => {
      unregister(command, idRef.current!);
    };
  }, [register, unregister, handler, command, ...otherDeps]);
}
