import jsBridgePostMessage from '@/services/JsBridge/jsBridgePostMessage';
import useRegisterMessage from '@/services/JsBridge/useRegisterMessage';
import { history } from '@umijs/max';
import { useCallback } from 'react';

// 当前hooks是全局指令的监听逻辑，通过路由传参实现全局监听和路由页面中逻辑的解耦
// 1、 入口监听插件指令，向下分发，主要是监听指令跳转到对应路由，指令和携带的参数会放到跳转到路由的state中
// 2、跳转到路由的页面中后，路由中写监听state的逻辑，判断如果存有指令信息则执行这个信息
// 3、路由中携带的state逻辑执行完毕后手动清除掉，避免刷新页面后再次命中指令的逻辑
const useChangeRoute = () => {
  const changeTabAndRoute = (key: string, state?: any) => {
    console.log('tab切换路由切换：', { key, state });
    history.push(
      {
        pathname: `/${key}`,
      },
      state,
    );
  };
  // 全局监听插件通信，跳转对应路由
  // @ts-ignore
  const onInlineChat = useCallback((data) => {
    jsBridgePostMessage({
      command: 'setPluginConfig',
      data: {
        mode: 'chat',
      },
    });
    changeTabAndRoute('oldChat', {
      command: 'onInlineChat',
      data,
    });
  }, []);
  useRegisterMessage('inlineChat', onInlineChat);
};
export default useChangeRoute;
