import { MsgMap } from '@/pages/Agentic/type';
import { StateCreator } from 'zustand';
import { StoreActions, StoreState } from './types';

export const actions: StateCreator<
  StoreState & StoreActions,
  [],
  [],
  StoreActions
> = (set, get) => ({
  setAgentModel(newModel) {
    set({
      agentModel: newModel,
    });
  },
  setMsgMap(msgMap) {
    set({ msgMap });
  },
  addMessage(msg) {
    const { messageId } = msg;
    set((state) => ({
      msgMap: {
        ...state.msgMap,
        [messageId]: { ...msg },
      },
    }));
  },
  updateMessage(messageId, updates) {
    set((state) => {
      const existingMsg = state.msgMap[messageId];
      if (!existingMsg) return state;

      return {
        msgMap: {
          ...state.msgMap,
          [messageId]: {
            ...existingMsg,
            ...updates,
          },
        },
      };
    });
  },
  setChatId(chatId) {
    set({ chatId });
  },
  setLoading(loading) {
    set({ loading });
  },
  setEditFileList: (list) => set({ editFileList: list }),
  setSelectedCodeList: (list) => set({ selectedCodeList: list }),
  setAddData(addData) {
    set({ addData });
  },
  setIsTokenOver(isTokenOver) {
    set({ isTokenOver });
  },
  setSelectedMessageId(messageId) {
    set({ selectedMessageId: messageId });
  },
  setButtonState(messageId, buttonState) {
    set((state) => ({
      buttonStateMap: {
        ...state.buttonStateMap,
        [messageId]: buttonState,
      },
    }));
  },
  setLatestUserMessageId(messageId) {
    set({ latestUserMessageId: messageId });
  },
  clearMessagesAfter(messageId) {
    set((state) => {
      const msgArray = Object.values(state.msgMap);
      const targetIndex = msgArray.findIndex(
        (msg) => msg.messageId === messageId,
      );
      if (targetIndex === -1) return state;

      const newMsgMap: MsgMap = {};
      msgArray.slice(0, targetIndex).forEach((msg) => {
        newMsgMap[msg.messageId] = msg;
      });

      return { msgMap: newMsgMap };
    });
  },
});
