import { useModel } from '@umijs/max';
import { once } from 'lodash';
import { useCallback, useEffect } from 'react';
import jsBridgePostMessage from './jsBridgePostMessage';

let pollCount = 0;

const initFinish = once(() => {
  jsBridgePostMessage({
    command: 'initFinish',
  });
});

export default function useProcessMessage() {
  const { handlers } = useModel('messageRegister');

  const processMessage = useCallback(
    (e: MessageEvent<JsBridgeMessage>) => {
      const { data: message } = e;
      // vscode 端专门用于处理回调的消息，单独处理
      if (message?.vscodeCallbackId) {
        return;
      }
      const { command, data } = message;
      if (!command) return;
      const targetCommand = handlers[command] || [];
      targetCommand.forEach(({ handler }) => {
        if (handler) {
          try {
            handler(data);
          } catch (e) {
            console.error(e);
          }
        }
      });
    },
    [handlers],
  );
  const initFinishPoll = () => {
    if (pollCount++ > 10) return;
    if (window?.JavaPanelBridge || window?.pluginConfig?.ide === 'vscode') {
      initFinish();
      return;
    }
    setTimeout(initFinishPoll, 300);
  };
  useEffect(() => {
    window.addEventListener('message', processMessage);
    // 挂载数据监听事件后发一个初始化结束的消息
    if ('syncPluginConfig' in handlers) {
      initFinishPoll();
    }
    return () => {
      window.removeEventListener('message', processMessage);
    };
  }, [processMessage]);
}
